 const STAGES = ["idle", "touching", "effects", "chance", "presses", "turns", "done"];
function stageAt(s) { return STAGES.indexOf(s); }
;
;
;function signed8(v) { const b = (v % 256 + 256) % 256; return b < 128 ? b : b - 256; }
function signed16(v) { const w = (v % 65536 + 65536) % 65536; return w < 32768 ? w : w - 65536; }
function byte(v) { return (v % 256 + 256) % 256; }
function word(v) { return (v % 65536 + 65536) % 65536; }
function countDown(n) { return byte(n - 1); }
function rgb(red, green, blue) { return red + 8 * green + 64 * blue; }
;function arcadeColor(byte) {
    const ladder = (level, ohms) => {
        const g = ohms.map((r) => 1 / r), all = g.reduce((a, b) => a + b, 0);
        return Math.round(255 * g.reduce((a, gi, i) => a + (Math.floor(level / 2 ** i) % 2) * gi, 0) / all);
    };
    const red = byte % 8, green = Math.floor(byte / 8) % 8, blue = Math.floor(byte / 64);
    return ladder(red, [1200, 560, 330]) * 65536 + ladder(green, [1200, 560, 330]) * 256 + ladder(blue, [560, 330]);
}
;function wallClock() { return performance.now(); } /*$b*/ return { STAGES, stageAt, signed8, signed16, byte, word, countDown, rgb, arcadeColor, wallClock };
